// models/product.js — MySQL (Sequelize), Phase 3 schema v1
//
// New in v1 (applied to existing DBs by backend/migrations/003_products_catalog_fields.sql):
//   slug       — URL-safe unique identifier (generated by the API layer)
//   stock      — product-level inventory count (moves to variants in a later phase)
//   imageMeta  — JSON metadata for the primary image, e.g. { "alt", "width", "height" }
//   categoryId — FK to Categories.id (legacy free-text `category` kept for backward compat)
const { DataTypes } = require("sequelize");
const sequelize = require("../config/db");
const Category = require("./category");

const Product = sequelize.define("Product", {
  name: {
    type: DataTypes.STRING,
    allowNull: false
  },
  category: {
    type: DataTypes.STRING, // legacy free-text category (retained in v1)
    allowNull: false
  },
  description: {
    type: DataTypes.TEXT
  },
  mrpPrice: {
    type: DataTypes.FLOAT,
    allowNull: false
  },
  sellingPrice: {
    type: DataTypes.FLOAT,
    allowNull: false
  },
  image: {
    type: DataTypes.STRING // URL or /uploads/<filename>
  },
  slug: {
    type: DataTypes.STRING(160),
    allowNull: false,
    unique: true
  },
  stock: {
    type: DataTypes.INTEGER,
    allowNull: false,
    defaultValue: 0
  },
  imageMeta: {
    type: DataTypes.JSON
  },
  categoryId: {
    type: DataTypes.INTEGER,
    allowNull: true
  }
}, {
  timestamps: true
});

Category.hasMany(Product, {
  foreignKey: { name: "categoryId", allowNull: true },
  onDelete: "SET NULL",
  onUpdate: "CASCADE"
});
Product.belongsTo(Category, {
  foreignKey: { name: "categoryId", allowNull: true },
  onDelete: "SET NULL",
  onUpdate: "CASCADE"
});

module.exports = Product;
